        }
      } else {
        await pass(card.id);
      }
    }
    setIdx(i => Math.min(i + 1, list.length));
    setInfo(false);
    setShowPulse(false);
  }, [card, list.length]);

  const swipe = useSwipe(handleAction);

  return (
