import { ModeKey } from "./modes";

export interface Profile {
  id: string;
  name: string;
  age: number;
  mode: ModeKey;
  bio: string;
  distance: number;
  time: string;
  color: string;
  photo: string;
  photos: string[];
  // Mode-specific
  cuisine?: string;
  event?: string;
  eventType?: string;
  from?: string;
  badge?: string;
  langs?: string[];
  safe?: boolean;
  since?: string;
  neighborhood?: string;
  ambassador?: boolean;
  speaks?: string[];
  learns?: string;
  level?: string;
  dog?: string;
  breed?: string;
  dogAge?: string;
}

// Realistic profile photos via randomuser.me (consented photos)
// Using specific seeds for consistent faces across renders
function photo(gender: "women" | "men", id: number): string {
  return `https://randomuser.me/api/portraits/${gender}/${id}.jpg`;
}

// Generate multiple photos per profile for the carousel
function photos(gender: "women" | "men", id: number): string[] {
  const base = photo(gender, id);
  // Use nearby IDs for additional photos (same gender, different person angle feel)
  return [
    base,
    photo(gender, (id + 1) % 100),
    photo(gender, (id + 3) % 100),
    photo(gender, (id + 7) % 100),
  ];
}

